% Input data
int: n = 20; % total steps
int: m1 = 3; % minimum steps at a time
int: m2 = 5; % maximum steps at a time

% Decision Variables
array[1..n] of var 0..m2: steps;

% Constraints
constraint sum(i in 1..n) (steps[i]) = n;
constraint forall(i in 1..n) (steps[i] >= 0);
constraint forall(i in 1..n) (steps[i] <= m2);
constraint forall(i in 1..n) (steps[i] = 0 \/
                              steps[i] = m1 \/
                              steps[i] = m1 + 1 \/
                              steps[i] = m1 + 2);

% Objective
solve satisfy;

% Output
output [
    "{",
    "\"steps\": [",
    join(", ", [show(steps[i]) | i in 1..n]),
    "]",
    "}"
];
```

