include "globals.mzn";

% Input data
int: num_countries = 5;
int: num_colours = 5; % maximum number of colours
array[1..num_countries, 1..num_countries] of bool: adjacency =
  [
    [false, true, true, false, false],
    [true, false, true, true, true],
    [true, true, false, true, false],
    [false, true, true, false, true],
    [false, true, false, true, false]
  ];

% Decision Variables
array[1..num_countries] of var 1..num_colours: colours;

% Constraints
constraint forall(i in 1..num_countries, j in i+1..num_countries) (
  adjacency[i, j] -> colours[i] != colours[j]
);

% Objective: minimize the number of colours used
var int: num_used_colours = max(colours);

% Solve
solve minimize num_used_colours;

% Print the solution in JSON format
output [
  "{",
  "\"colors\": [",
  join(", ", [show(colours[i]) | i in 1..num_countries]),
  "]",
  "}"
];
