```minizinc
% Import necessary libraries
include "globals.mzn";

% Number of cows
int: num_cows = 25;

% Number of sons
int: num_sons = 5;

% Number of cows each son should have
array[1..num_sons] of int: cows_per_son = [7, 6, 5, 4, 3];

% Decision variable: assignment of cows to sons
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Constraint: each son should have the correct number of cows
constraint forall(i in 1..num_sons) (
    sum(j in 1..num_cows) (cow_assignments[j] == i-1) = cows_per_son[i]
);

% Constraint: the total quantity of milk produced should be the same for each son
constraint forall(i, j in 1..num_sons where i < j) (
    sum(k in 1..num_cows where cow_assignments[k] == i-1) (k) =
    sum(k in 1..num_cows where cow_assignments[k] == j-1) (k)
);

% Solve the model
solve satisfy;

% Print the solution in JSON format
output [
    "{",
    "\"cow_assignments\": [",
    join(", ", [show(cow_assignments[i]) | i in 1..num_cows]),
    "]",
    "}"
];
```

