    let {
        int: num_males_so_far = sum([sequence[j] = 0 | j in 1..i]);
        int: num_females_so_far = sum([sequence[j] = 1 | j in 1..i]);
    } in
    num_males_so_far > 0 -> num_females_so_far / num_males_so_far <= 7/3
);

% Solve the problem
solve satisfy;

% Print the solution
output [
    "{",
    "\"sequence\": [",
    join(", ", [show(sequence[i]) | i in 1..num_people]),
    "]",
    "}"
];
