% Input data
int: num_slots = 6;
array[1..num_slots] of int: demands = [4, 8, 10, 7, 12, 4];

% Decision Variables
array[1..num_slots] of int: x;

% Constraints
constraint forall(i in 1..num_slots) (x[i] >= demands[i]);

% To account for buses transitioning between intervals
% We need to ensure that the number of buses available in each 4-hour interval
% meets the demand for that interval and the previous interval
constraint forall(i in 2..num_slots) (x[i] + x[i-1] >= demands[i] + demands[i-1]);

% Each bus can operate only 8 successive hours a day
% So, we need to ensure that the number of buses available in each 4-hour interval
% does not exceed the number of buses available in the previous two intervals
constraint forall(i in 3..num_slots) (x[i] <= x[i-1] + x[i-2]);

% Objective: minimize the total number of buses
solve minimize sum(x);

% Print the solution in JSON format
output [
    "{",
    "\"x\": [",
    join(", ", [show(xi) | xi in x]),
    "]",
    "}"
];
