array[int] of var int: end_time = [var 0..1000 | i in 1..num_jobs];

% Constraints
constraint forall(i in 1..num_jobs) (
    start_time[i, 1] == 0
);

constraint forall(i in 1..num_jobs, j in 2..length(jobs_data[i])) (
    start_time[i, j] >= start_time[i, j-1] + jobs_data[i][j-1]
);

constraint forall(i in 1..num_machines) (
    task_duration[i] == sum([jobs_data[j][k] | j in 1..num_jobs, k in 1..length(jobs_data[j]) where jobs_data[j][k] > 0])
);

