constraint forall(i in 1..num_items) (pos_y[i] >= 0);
constraint forall(i in 1..num_items) (pos_x[i] + widths[i] <= total_x);
constraint forall(i in 1..num_items) (pos_y[i] + heights[i] <= total_y);

% Non-overlap constraints
constraint forall(i in 1..num_items, j in i+1..num_items) (
    (pos_x[i] + widths[i] <= pos_x[j]) \/
    (pos_x[j] + widths[j] <= pos_x[i]) \/
    (pos_y[i] + heights[i] <= pos_y[j]) \/
    (pos_y[j] + heights[j] <= pos_y[i])
);

% Objective: Minimize total area
solve minimize total_x * total_y;

