% Constraints
constraint forall(i in 1..9, j in 1..9) (
    input_grid[i, j] > 0 -> grid[i, j] = input_grid[i, j]
);

% Each row contains all digits from 1 to 9
constraint forall(i in 1..9) (
    alldifferent([grid[i, j] | j in 1..9])
);

% Each column contains all digits from 1 to 9
constraint forall(j in 1..9) (
    alldifferent([grid[i, j] | i in 1..9])
);

% Each 3x3 section contains all digits from 1 to 9
constraint forall(i in 1..3, j in 1..3) (
    alldifferent([grid[3*(i-1)+k, 3*(j-1)+l] | k in 1..3, l in 1..3])
);

% Solve the model
solve satisfy;

% Print the solution in JSON format
output [
    "{",
