  constraint boat_pos[i+1] == 1 - boat_pos[i];
end for;

% Farmer is with the boat
for i in 1..stage do
  constraint wolf_pos[i] == boat_pos[i] \/ (wolf_pos[i] == 0 /\ boat_pos[i] == 0);
