% Import necessary libraries
include "globals.mzn";

% Input data
int: n_weeks = 4;  % Number of weeks
int: n_groups = 3;  % Number of groups
int: group_size = 3;  % Size of each group
int: n_golfers = n_groups * group_size;  % Total number of golfers

% Decision Variables
array[1..n_weeks, 1..n_groups, 1..group_size] of var 1..n_golfers: assign;

% Constraints
% Each golfer plays once a week
constraint forall(w in 1..n_weeks) (
    forall(g1 in 1..n_groups, g2 in g1+1..n_groups) (
        forall(p1 in 1..group_size, p2 in 1..group_size) (
            assign[w, g1, p1] != assign[w, g2, p2]
        )
    )
);

% No golfer plays in the same group as any other golfer twice
constraint forall(g1 in 1..n_golfers, g2 in g1+1..n_golfers) (
    sum(w in 1..n_weeks, g in 1..n_groups) (
        (assign[w, g, 1] == g1 /\ assign[w, g, 2] == g2) \/
        (assign[w, g, 1] == g1 /\ assign[w, g, 3] == g2) \/
        (assign[w, g, 2] == g1 /\ assign[w, g, 3] == g2)
    ) <= 1
);

% Each golfer plays with every other golfer at most once
constraint forall(w in 1..n_weeks) (
    forall(g in 1..n_groups) (
        forall(p1 in 1..group_size, p2 in p1+1..group_size) (
            assign[w, g, p1] < assign[w, g, p2]
        )
    )
);

% Solve the model
solve satisfy;

% Print the solution in JSON format
output [
    "{",
    "\"assign\": [",
    join(",\n", [
        "[" ++ join(", ", [show(assign[w, g, p]) | p in 1..group_size]) ++ "]"
        | w in 1..n_weeks, g in 1..n_groups
    ]),
    "]",
    "}"
];
