% Import necessary libraries
include "globals.mzn";

% Input data
int: n_boats = 5;  % Number of boats
int: n_periods = 4;  % Number of periods
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];  % Capacities of the boats
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];  % Crew sizes of the boats

% Decision Variables
array[1..n_boats] of bool: is_host;  % Whether a boat is a host
array[1..n_boats, 1..n_periods] of var 1..n_boats: visits;  % Visit schedule

% Constraints
constraint forall(b in 1..n_boats) (
    if is_host[b] then
        forall(p in 1..n_periods) (
            visits[b, p] = b
        )
    else
        forall(p in 1..n_periods) (
            visits[b, p] in 1..n_boats
        ) /\
        forall(p1, p2 in 1..n_periods where p1 < p2) (
            visits[b, p1] != visits[b, p2]
        ) /\
        forall(p in 1..n_periods) (
            is_host[visits[b, p]]
        )
    );

constraint forall(h in 1..n_boats where is_host[h]) (
    forall(p in 1..n_periods) (
        sum(b in 1..n_boats where not is_host[b] and visits[b, p] = h) (crew_size[b]) + crew_size[h] <= capacity[h]
    )
);

constraint forall(b1, b2 in 1..n_boats where b1 < b2 and not is_host[b1] and not is_host[b2]) (
    forall(p in 1..n_periods) (
        visits[b1, p] != visits[b2, p]
    )
);

% Objective: Minimize the number of host boats
solve minimize sum(b in 1..n_boats) (bool2int(is_host[b]));

% Print the solution
output [
    "{",
    "\"visits\": [",
    join(",\n", [
        "[" ++ join(", ", [show(visits[b, p]) | p in 1..n_periods]) ++ "]"
        | b in 1..n_boats
    ]),
    "],",
    "\"is_host\": [",
    join(", ", [show(bool2int(is_host[b])) | b in 1..n_boats]),
    "]",
    "}"
];
