array[1..n_teams] of var bool: home;

% Constraints
constraint forall(w in 1..n_weeks, p in 1..n_periods) (
    team[w, p, 1] != team[w, p, 2]
);

constraint forall(w in 1..n_weeks, p in 1..n_periods, s in 1..n_slots) (
    team[w, p, s] >= 1
);

constraint forall(t in 1..n_teams) (
    forall(w in 1..n_weeks, p in 1..n_periods, s in 1..n_slots) (
        team[w, p, s] != t
    ) <-> not home[t]
);

constraint forall(t1 in 1..n_teams, t2 in t1+1..n_teams) (
    exists(w in 1..n_weeks, p in 1..n_periods) (
        (team[w, p, 1] = t1 /\ team[w, p, 2] = t2) \/ (team[w, p, 1] = t2 /\ team[w, p, 2] = t1)
    )
);

constraint forall(t in 1..n_teams) (
    sum(w in 1..n_weeks, p in 1..n_periods, s in 1..n_slots) (team[w, p, s] = t) = n_teams - 1
);

% Double round robin
array[1..n_weeks, 1..n_periods, 1..n_slots] of var 0..n_teams-1: away_team;
constraint forall(w in 1..n_weeks, p in 1..n_periods) (
    away_team[w, p, 1] = team[w, p, 2]
);
constraint forall(w in 1..n_weeks, p in 1..n_periods) (
    away_team[w, p, 2] = team[w, p, 1]
);

% Solve
solve satisfy;

% Output
output [
    "{",
