    join(", ", [show([team[w, p, 1] | p in 1..n_periods]) | w in 1..n_weeks]),
    "],",
    "\"away\": [",
    join(", ", [show([away_team[w, p, 1] | p in 1..n_periods]) | w in 1..n_weeks]),
    "]",
    "}"
];
