% Input data
int: n = 8;  % Size of the Costas array

% Decision Variables
array[1..n] of var 1..n: x;  % Costas array

% Constraints
constraint all_different(x);  % Each row and column has a unique mark

% Difference triangle constraints
for l in 1..n-1 do
  array[1..n-l] of var -n+1..n-1: x_diff_l;
  for i in 1..n-l do
    constraint x_diff_l[i] = x[i] - x[i+l];
  end for;
  constraint all_different(x_diff_l);
end for;

% Solve the model
solve satisfy;

% Print the solution in JSON format
output [
  "{",
  "\"costas\": [",
  join(", ", [show([x[j] | j in 1..n]) | i in 1..1]),
  "]",
  "}"
];
```

