  if (x[i] in allowed_neighbors[x[i+1]]) \/ (x[i+1] in allowed_neighbors[x[i]]) then 1 else 0
);

% Print the seating order
output [
  "{",
  "\"x\": [",
  join(", ", [show(x[i]) | i in 1..n]),
  "]",
  "}"
];
