array[WAREHOUSES] of int: fixed_costs = [400, 500, 300, 150];  % Weekly fixed costs per warehouse
int: max_shipping = 100;  % Max units per week per warehouse
array[REGIONS] of int: demands = [80, 70, 40];  % Weekly demands for regions 1 to 3
array[WAREHOUSES, REGIONS] of int: shipping_costs = [
    [20, 40, 50],  % New York to regions 1, 2, 3
    [48, 15, 26],  % Los Angeles to regions 1, 2, 3
    [26, 35, 18],  % Chicago to regions 1, 2, 3
    [24, 50, 35]  % Atlanta to regions 1, 2, 3
];

% Decision Variables
array[WAREHOUSES] of var bool: open_warehouse;  % Whether a warehouse is open
array[WAREHOUSES, REGIONS] of var int: ships;  % Shipping details for each region per warehouse

% Objective variable
var int: total_cost;

% Constraints
constraint forall(w in WAREHOUSES, r in REGIONS) (ships[w, r] >= 0);
constraint forall(w in WAREHOUSES) (sum(r in REGIONS) (ships[w, r]) <= max_shipping * bool2int(open_warehouse[w]));
constraint forall(r in REGIONS) (sum(w in WAREHOUSES) (ships[w, r]) == demands[r]);
